/*getPwFindCheck*/
SELECT USER_ID
  FROM ICOMLUSR
 WHERE     USER_ID = #{st_id}
       AND USER_NAME_LOC = #{st_name}
       AND UPPER(EMAIL) = UPPER(#{st_mail_addr})
       AND MOBILE_PHONE = #{st_phone_num1}||'-'||#{st_phone_num2}||'-'||#{st_phone_num3}
       AND STATUS IN ('C', 'R')

/*getNewAgentHomeboardSelList*/ SELECT YY.* FROM( SELECT ROWNUM NUM, XX.* FROM( SELECT ZZ.* FROM (
SELECT BID, COMPANY, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = COMPANY) COM_NAME_LOC, SUBSTRB(SUBJECT,1,80) SUBJECT, REG_USER_NAME, (SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = COMPANY AND USER_ID = REG_USER_ID) EMAIL, REG_DATE, (SELECT MAX(BID) FROM ICOMBOARD WHERE STATUS ! ='D' AND BTYPE IN ('BD','NT') AND ACL = 'CST' AND OPEN_FLAG = 'Y' AND BTYPE||BID||COMPANY IN (SELECT BTYPE||BID||COMPANY FROM ICOMBDDT WHERE COM_CODE = #{st_com_code})) MAX_BID, (SELECT MIN(BID) FROM ICOMBOARD WHERE STATUS ! ='D' AND BTYPE IN ('BD','NT') AND ACL = 'CST' AND OPEN_FLAG = 'Y' AND BTYPE||BID||COMPANY IN (SELECT BTYPE||BID||COMPANY FROM ICOMBDDT WHERE COM_CODE = #{st_com_code})) MIN_BID, ACL, LCOUNT, BTYPE, TO_DATE, BLEVEL, VID, DECODE(ACL,'INC','자사', 'BUY','구매사', 'SEL','판매사', 'KEP','KEP', 'MEB','회원전체', 'CST','특정회사', 'UST','특정사용자', 'ALL','전체') ACL_DIS, IMAGE_KEY
From ICOMBOARD Where STATUS ! ='D' AND FROM_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') And BTYPE IN ('BD','NT') AND ACL = 'CST' AND OPEN_FLAG = 'Y' AND BTYPE||BID||COMPANY IN (SELECT BTYPE||BID||COMPANY FROM ICOMBDDT WHERE COM_CODE = #{st_com_code})
UNION
SELECT BID, COMPANY, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = COMPANY) COM_NAME_LOC, SUBSTRB(SUBJECT,1,80) SUBJECT, REG_USER_NAME, (SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = COMPANY AND USER_ID = REG_USER_ID) EMAIL, REG_DATE, (SELECT MAX(BID) FROM ICOMBOARD WHERE STATUS ! ='D' AND FROM_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND BTYPE IN ('BD','NT') AND ACL IN ('SEL','ALL')) MAX_BID, (SELECT MIN(BID) FROM ICOMBOARD WHERE STATUS ! ='D' AND FROM_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND BTYPE IN ('BD','NT') AND ACL IN ('SEL','ALL')) MIN_BID, ACL, LCOUNT, BTYPE, TO_DATE, BLEVEL, VID, DECODE(ACL,'INC','자사', 'BUY','구매사', 'SEL','판매사', 'KEP','KEP', 'MEB','회원전체', 'CST','특정회사', 'UST','특정사용자', 'ALL','전체') ACL_DIS, IMAGE_KEY FROM ICOMBOARD WHERE STATUS ! ='D' AND FROM_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND BTYPE IN ('BD','NT') AND OPEN_FLAG = 'Y' AND ACL IN ('SEL','ALL')
) ZZ Order By REG_DATE DESC , VID desc )XX )YY WHERE NUM BETWEEN 1 AND 5

