SELECT BID, COMPANY, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = COMPANY) COM_NAME_LOC, SUBSTRB(SUBJECT,1,80) SUBJECT, REG_USER_NAME, (SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = COMPANY AND USER_ID = REG_USER_ID) EMAIL, REG_DATE, (SELECT MAX(BID) FROM ICOMBOARD WHERE STATUS ! ='D' AND FROM_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND BTYPE IN ('BD','NT') AND ACL IN ('EXP','ALL')) MAX_BID, (SELECT MIN(BID) FROM ICOMBOARD WHERE STATUS ! ='D' AND FROM_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND BTYPE IN ('BD','NT') AND ACL IN ('EXP','ALL')) MIN_BID, ACL, LCOUNT, BTYPE, TO_DATE, BLEVEL, VID, DECODE(ACL,'INC','자사', 'BUY','구매사', 'SEL','판매사', 'KEP','KEP', 'MEB','회원전체', 'CST','특정회사', 'UST','특정사용자', 'EXP','수출', 'ALL','전체') ACL_DIS, IMAGE_KEY FROM ICOMBOARD WHERE STATUS ! ='D' AND FROM_DATE <= TO_CHAR(SYSDATE, 'YYYYMMDD') AND TO_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND BTYPE IN ('BD','NT') AND OPEN_FLAG = 'Y' AND ACL IN ('EXP','ALL')
) ZZ Order By REG_DATE DESC , VID desc )XX )YY WHERE NUM BETWEEN 1 AND 5

/*getNoticeList*/ SELECT /*+ index_asc(icomboard icomboard_pk) */ BID, COMPANY, SUBJECT, REG_USER_NAME, (SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = COMPANY AND USER_ID = REG_USER_ID) EMAIL, REG_DATE, (SELECT MAX (BID) FROM ICOMBOARD WHERE STATUS != 'D' AND BTYPE = #{BTYPE} ${WHERE}) MAX_BID, (SELECT MIN (BID) FROM ICOMBOARD WHERE STATUS != 'D' AND BTYPE = #{BTYPE} ${WHERE}) MIN_BID, ACL, LCOUNT, DECODE (BTYPE, 'NT', '공지사항', 'EB', 'e-Biz뉴스', 'DI', '전시회소식', 'EM', 'e마켓자료실', 'SI', '상품자료실', 'PI', '구매정보') BTYPE_DIS, DECODE (ACL, 'INC', '자사', 'BUY', '구매사', 'SEL', '판매사', 'KEP', 'KEP', 'MEB', '회원전체', 'CST', '특정회사', 'UST', '특정사용자', 'ALL', '전체') ACL_DIS, BTYPE FROM ICOMBOARD WHERE STATUS != 'D' AND BTYPE = #{BTYPE} ${WHERE}
AND REG_USER_NAME LIKE '%'||#{search_word}||'%'
AND SUBJECT LIKE '%'||#{search_word}||'%'
ORDER BY BID DESC


