/* getExportHomeChartList */ SELECT SUM(A.CI_JAN) AS CI_JAN, SUM(A.BL_JAN) AS BL_JAN, SUM(A.CI_FEB) AS CI_FEB, SUM(A.BL_MAR) AS BL_MAR, SUM(A.CI_APR) AS CI_APR, SUM(A.BL_APR) AS BL_APR, SUM(A.CI_MAY) AS CI_MAY, SUM(A.BL_MAY) AS BL_MAY, SUM(A.CI_JUN) AS CI_JUN, SUM(A.BL_JUN) AS BL_JUN, SUM(A.CI_JUL) AS CI_JUL, SUM(A.BL_JUL) AS BL_JUL, SUM(A.CI_AUG) AS CI_AUG, SUM(A.BL_AUG) AS BL_AUG, SUM(A.CI_SEP) AS CI_SEP, SUM(A.BL_SEP) AS BL_SEP, SUM(A.CI_OCT) AS CI_OCT, SUM(A.BL_OCT) AS BL_OCT, SUM(A.CI_NOV) AS CI_NOV, SUM(A.BL_NOV) AS BL_NOV, SUM(A.CI_DEC) AS CI_DEC, SUM(A.BL_DEC) AS BL_DEC FROM ( SELECT DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '01', COUNT(*), 0) AS CI_JAN, 0 AS BL_JAN, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '02', COUNT(*), 0) AS CI_FEB, 0 AS BL_FEB, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '03', COUNT(*), 0) AS CI_MAR, 0 AS BL_MAR, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '04', COUNT(*), 0) AS CI_APR, 0 AS BL_APR, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '05', COUNT(*), 0) AS CI_MAY, 0 AS BL_MAY, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '06', COUNT(*), 0) AS CI_JUN, 0 AS BL_JUN, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '07', COUNT(*), 0) AS CI_JUL, 0 AS BL_JUL, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '08', COUNT(*), 0) AS CI_AUG, 0 AS BL_AUG, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '09', COUNT(*), 0) AS CI_SEP, 0 AS BL_SEP, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '10', COUNT(*), 0) AS CI_OCT, 0 AS BL_OCT, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '11', COUNT(*), 0) AS CI_NOV, 0 AS BL_NOV, DECODE(TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY') || '12', COUNT(*), 0) AS CI_DEC, 0 AS BL_DEC FROM KEP_EXP_CIHD WHERE 1=1 AND PKG_COMPANY_CODE = #{st_com_code} AND STATUS IN ('C', 'R') AND TO_CHAR(ADD_DATE, 'YYYYMM') BETWEEN TO_CHAR(SYSDATE, 'YYYY') || '01' AND TO_CHAR(SYSDATE, 'YYYY') || '12' GROUP BY TO_CHAR(ADD_DATE, 'YYYYMM'), TO_CHAR(ADD_DATE, 'YYYY')
UNION ALL
SELECT 0 AS CI_JAN, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '01', COUNT(*), 0) AS BL_JAN, 0 AS CI_FEB, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '02', COUNT(*), 0) AS BL_FEB, 0 AS CI_MAR, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '03', COUNT(*), 0) AS BL_MAR, 0 AS CI_APR, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '04', COUNT(*), 0) AS BL_APR, 0 AS CI_MAY, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '05', COUNT(*), 0) AS BL_MAY, 0 AS CI_JUN, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '06', COUNT(*), 0) AS BL_JUN, 0 AS CI_JUL, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '07', COUNT(*), 0) AS BL_JUL, 0 AS CI_AUG, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '08', COUNT(*), 0) AS BL_AUG, 0 AS CI_SEP, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '09', COUNT(*), 0) AS BL_SEP, 0 AS CI_OCT, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '10', COUNT(*), 0) AS BL_OCT, 0 AS CI_NOV, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '11', COUNT(*), 0) AS BL_NOV, 0 AS CI_DEC, DECODE(TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') || '12', COUNT(*), 0) AS BL_DEC FROM KEP_EXP_BLHD BH, KEP_EXP_BLDT BD, KEP_EXP_CIHD CH WHERE 1=1 AND BH.BUYER = BD.BUYER AND BH.PKG_COMPANY_CODE = BD.PKG_COMPANY_CODE AND BH.BL_NO = BD.BL_NO AND BD.BUYER = CH.BUYER AND BD.PKG_COMPANY_CODE = CH.PKG_COMPANY_CODE AND BD.CI_NO = CH.CI_NO AND CH.STATUS IN ('C', 'R') AND BH.PKG_COMPANY_CODE = #{st_com_code} AND TO_CHAR(BH.ADD_DATE, 'YYYYMM') BETWEEN TO_CHAR(SYSDATE, 'YYYY') || '01' AND TO_CHAR(SYSDATE, 'YYYY') || '12' GROUP BY TO_CHAR(BH.ADD_DATE, 'YYYYMM'), TO_CHAR(BH.ADD_DATE, 'YYYY') ) A


/*getSubPwInsert*/
SELECT	DECODE(COUNT(*), 0, 'N', 'Y') AS RESULT
FROM	ICOMLUSR A
WHERE	1=1
AND		USER_ID = #{USER_ID}
AND		PASSWORD = #{NEW_PW}
